// import React from 'react';
import React, { useState, useEffect } from 'react';
import axios from 'axios';
import { Link } from 'react-router-dom';

import Sidebar from '../About/Sidebar';

export default function AddCommission() {

  const [name, setName] = useState('');
  const handleSubmit = async (event) => {
    event.preventDefault();

    try {
      await axios.post('http://localhost:5000/commission', { name });
      alert('Commission type added successfully');
      setName(''); // Clear the form after successful submission
    } catch (error) {
      console.error('Error adding commission type:', error);
      alert('Failed to add commission type');
    }
  };

  return (

    <div className="wrapper">
      {/* Topheader on page  */}
      <Topheader />

      {/* sidebar menu */}
      <Leftsidebar />

      {/* Content goes to hare */}
      <div className="content-wrapper">
        <section className="content">
          {/* <div className="container-fluid"> */}
          {/* content goes to hare  */}

          <div className="container mt-3">
            <div className="card card-default">
              <div className="card-header">
                <h3 className="card-title mt-3">Commission Type</h3>
                <div className="card-tools">
                  {/* <a href="/commission" className="btn btn-sm btn-success"> All </a> */}
                  <Link to="/commission" className="btn btn-sm btn-success">All</Link>
                </div>
              </div>

              <div className="form-Container m-3">
                {/* <form onSubmit={handleSubmit}>
                  <div className="row">
                    <div className="col-6 d-flex flex-column  mb-2">
                      <label for="">Name:<span className="required">*</span></label>
                      <input className="form-control" type="text" name="name" placeholder="Enter Name" />
                      <span style={{ fontSize: '12px' }}>(Commission Type (CPA, CPL, CPI, CPS, RevShare, etc))</span>
                    </div>
                  </div>

                  <div className="row mt-3">
                    <div className="col-6">
                      <input type="submit" className="btn btn-success btn-md" />
                    </div>
                  </div>
                </form> */}
                <form onSubmit={handleSubmit}>
                  <div className="row">
                    <div className="col-6 d-flex flex-column  mb-2">
                      <label for="">Name:<span className="required">*</span></label>
                      <input className="form-control" type="text" value={name} onChange={(e) => setName(e.target.value)} required />
                      <span style={{ fontSize: '12px' }}>(Commission Type (CPA, CPL, CPI, CPS, RevShare, etc))</span>
                    </div>
                  </div>
                  <div className="row mt-3">
                    <div className="col-6">
                      <input type="submit" className="btn btn-success btn-md" />
                    </div>
                  </div>
                </form>


                {/* <form onSubmit={handleSubmit}>
                  <label>
                    Name:
                    <input
                      type="text"
                      value={name}
                      onChange={(e) => setName(e.target.value)}
                      required
                    />
                  </label>
                  <button type="submit">Submit</button>
                </form> */}
              </div>
            </div>
          </div>



          {/* </div> */}
        </section>
      </div>
    </div>
  )
}
